if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}
require_once __DIR__.'/../vendor/autoload.php';
$root=dirname(__DIR__);$excel=$argv[1]??$root.'/2024/Daftar Kontrak 2024.xlsx';$rabFile=$argv[2]??$root.'/2024/RAb Kontrak 2024.xlsx';
$c=include $root.'/config/database.php';$pdo=new PDO('mysql:unix_socket='.$c['socket'].';dbname='.$c['dbname'],$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec('SET NAMES utf8mb4 COLLATE utf8mb4_general_ci');$w='76.01';$o='1.03.0.00.0.00.01.0000';$y=2024;$actor='IMPORT_KONTRAK_EXCEL_DPPA_GROUP_2024';$norm=fn($v)=>preg_replace('/[^a-z0-9]+/',' ',mb_strtolower((string)$v,'UTF-8'));$tokens=function($v)use($norm){$stop=array_fill_keys(explode(' ','dan jalan pembangunan peningkatan pemeliharaan pengawasan perencanaan pemb pembangunan desa kabupaten kecamatan kegiatan pekerjaan umum paket'),true);return array_values(array_filter(explode(' ',trim($norm($v))),fn($x)=>strlen($x)>3&&!isset($stop[$x])));};$num=fn($v)=>is_numeric($v)?(float)$v:null;
$insert=function($t,$r)use($pdo){$c=array_keys($r);$m=implode(',',array_fill(0,count($c),'?'));$pdo->prepare('INSERT INTO `'.$t.'` (`'.implode('`,`',$c).'`) VALUES ('.$m.')')->execute(array_values($r));return(int)$pdo->lastInsertId();};
$reader=PhpOffice\PhpSpreadsheet\IOFactory::createReaderForFile($excel);$reader->setReadDataOnly(true);$s=$reader->load($excel)->getActiveSheet();$contracts=[];for($i=5;$i<=$s->getHighestRow();$i++){ $no=trim((string)$s->getCell("B$i")->getValue());$v=$num($s->getCell("M$i")->getValue());if(!preg_match('/^\d{3,15}$/',$no)||$v===null||$v<=0)continue;$raw=preg_replace('/\s+/u','',trim((string)$s->getCell("AF$i")->getValue()));preg_match('~1\.03(?:\.\d+){4,5}~',$raw,$m);$code=$m[0]??'';if(!$code)continue;$contracts[$no]=['no'=>$no,'code'=>$code,'package'=>trim((string)$s->getCell("C$i")->getValue()),'value'=>$v,'budget'=>$num($s->getCell("J$i")->getValue())??0,'vendor'=>trim((string)$s->getCell("N$i")->getValue()),'director'=>trim((string)$s->getCell("O$i")->getValue()),'npwp'=>trim((string)$s->getCell("Q$i")->getValue()),'address'=>trim((string)$s->getCell("R$i")->getValue()),'method'=>trim((string)$s->getCell("BI$i")->getValue()),'category'=>trim((string)$s->getCell("AE$i")->getValue()),'row'=>$i];}
$q=$pdo->prepare('SELECT id,kd_sub_keg,uraian,kelompok,komponen,jumlah,kd_akun FROM dppa_neo WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND is_deleted=0 AND jumlah>0 ORDER BY id');$q->execute([$w,$o,$y]);$groups=[];foreach($q as$r){$key=$r['kd_sub_keg'].'|'.trim((string)$r['kelompok']);$groups[$key]['code']=$r['kd_sub_keg'];$groups[$key]['label']=$r['kelompok'];$groups[$key]['rows'][]=$r;}
