$pdo->beginTransaction();try{$vendors=[];$ids=[];$itemCount=0;$rabCount=0;foreach($matched as$no=>$g){$x=$contracts[$no];$rows=$g['rows'];$pagu=array_sum(array_map(fn($r)=>(float)$r['jumlah'],$rows));foreach($rows as$r)$pdo->prepare('UPDATE dppa_neo SET setujui=1,kunci=1,tgl_update=NOW(),username_update=? WHERE id=?')->execute([$actor,$r['id']]);$vk=$norm($x['vendor']);if(!isset($vendors[$vk])){$v=$pdo->prepare('SELECT id,nama_perusahaan FROM rekanan_neo WHERE kd_wilayah=? AND is_deleted=0');$v->execute([$w]);$vid=null;foreach($v as$z)if($norm($z['nama_perusahaan'])===$vk)$vid=(int)$z['id'];if(!$vid)$vid=$insert('rekanan_neo',['kd_wilayah'=>$w,'nama_perusahaan'=>$x['vendor']?:'Tidak tercantum','alamat'=>$x['address']?:'-','npwp'=>$x['npwp']?:'-','direktur'=>$x['director']?:'-','disable'=>0,'is_deleted'=>0,'username_insert'=>$actor,'tgl_insert'=>date('Y-m-d H:i:s')]);$vendors[$vk]=$vid;}$kind=str_contains(strtoupper($x['category']),'KONSULT')?'KONSULTANSI_KONSTRUKSI':(str_contains(strtoupper($x['category']),'BARANG')?'BARANG':'PEKERJAAN_KONSTRUKSI');$id=$insert('kontrak_neo',['kd_wilayah'=>$w,'kd_opd'=>$o,'tahun'=>$y,'kd_sub_keg'=>$x['code'],'anggaran_id'=>(int)$rows[0]['id'],'rekanan_id'=>$vendors[$vk],'nama_sub_keg'=>$g['label'],'tahap'=>'dppa','cara_pengadaan'=>'PENYEDIA','jenis_pengadaan'=>$kind,'metode_pemilihan'=>$x['method'],'bentuk_kontrak'=>'SURAT_PERJANJIAN','total_anggaran'=>$pagu,'nilai_hps'=>$x['budget'],'nilai_kontrak'=>$x['value'],'nomor_kontrak'=>'600/'.$no,'uraian_kontrak'=>$x['package'],'nama_penyedia'=>$x['vendor'],'status_kontrak'=>'aktif','is_deleted'=>0,'keterangan'=>'Sumber Excel; matched kelompok DPPA '.$g['label'].'; subkegiatan '.$x['code'],'tgl_insert'=>date('Y-m-d H:i:s'),'username_insert'=>$actor]);$ids[]=$id;$left=$x['value'];foreach($rows as$ix=>$r){$a=$ix===array_key_last($rows)?$left:round($x['value']*$r['jumlah']/$pagu,2);$left-=$a;$insert('kontrak_item_neo',['kontrak_id'=>$id,'tahap'=>'dppa','anggaran_id'=>(int)$r['id'],'kd_wilayah'=>$w,'kd_opd'=>$o,'tahun'=>$y,'kd_sub_keg'=>$x['code'],'kd_akun'=>$r['kd_akun'],'uraian'=>$r['uraian'].' - '.$g['label'],'pagu'=>$r['jumlah'],'nilai_kontrak'=>$a,'username_insert'=>$actor,'tgl_insert'=>date('Y-m-d H:i:s'),'is_deleted'=>0]);$itemCount++;}foreach($rabs[$no]??[] as$rbrow){$insert('rab_paket_neo',['kontrak_id'=>$id,'tahun'=>$y,'kd_wilayah'=>$w,'kd_opd'=>$o,'id_renja_p'=>0,'id_dpa'=>0,'id_dppa'=>(int)$rows[0]['id'],'nomor'=>$rbrow['no'],'uraian'=>$rbrow['desc'],'satuan'=>$rbrow['unit'],'type'=>'RAB Excel 2024','vol_hps'=>$rbrow['vol'],'vol_penawaran'=>$rbrow['vol'],'vol_negoisasi'=>$rbrow['vol'],'harga_sat_hps'=>$rbrow['price'],'harga_sat_penawaran'=>$rbrow['price'],'harga_sat_negoisasi'=>$rbrow['price'],'jumlah_hps'=>$rbrow['amount'],'jumlah_penawaran'=>$rbrow['amount'],'jumlah_negoisasi'=>$rbrow['amount'],'bobot'=>0,'keterangan'=>'Sheet '.$no.' baris '.$rbrow['row'],'username_insert'=>$actor,'tgl_insert'=>date('Y-m-d H:i:s'),'is_deleted'=>0]);$rabCount++;}}$pdo->commit();echo json_encode(['matched_contracts'=>count($ids),'ambiguous_or_unmatched'=>count($exceptions),'contract_items'=>$itemCount,'rab_rows'=>$rabCount,'exceptions'=>array_slice($exceptions,0,20)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;}catch(Throwable$e){$pdo->rollBack();throw$e;}
